async function getCardStats() {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json() as Promise<{ totalRevenue: number; totalInvoices: number }>
}

export async function CardStats() {
  const { totalRevenue, totalInvoices } = await getCardStats()

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{totalInvoices}</p>
      </div>
    </div>
  )
}

async function getRevenue() {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json() as Promise<{ revenue: { month: string; amount: number }[] }>
}

export async function RevenueChart() {
  const { revenue } = await getRevenue()

  return (
    <div className="chart">
      <h2>Revenue</h2>
      <ul>
        {revenue.map((item) => (
          <li key={item.month}>
            {item.month}: ${item.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

async function getLatestInvoices() {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json() as Promise<{ invoices: { id: string; name: string; amount: number }[] }>
}

export async function LatestInvoices() {
  const { invoices } = await getLatestInvoices()

  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <ul>
        {invoices.map((invoice) => (
          <li key={invoice.id}>
            {invoice.name} - ${invoice.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

